"use client"

import { useCallback, useEffect, useRef, useState } from "react"
import "./styles.css"

export interface VideoTimestamp {
  label: string
}

export interface VideoFrame {
  image: string
}

export interface CustomVideoPlayerProps {
  src?: string
  timestamps?: VideoTimestamp[]
  frames?: VideoFrame[]
  autoPlay?: boolean
  muted?: boolean
  loop?: boolean
  className?: string
}

const DEFAULT_TIMESTAMPS: VideoTimestamp[] = [
  { label: "00:00" },
  { label: "00:05" },
  { label: "00:10" },
  { label: "00:15" },
  { label: "00:20" },
  { label: "00:25" },
  { label: "00:30" },
  { label: "00:35" },
  { label: "00:40" },
  { label: "00:45" },
  { label: "00:50" },
  { label: "00:55" },
  { label: "01:00" },
]

const DEMO_VIDEO =
  "https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4"

export function CustomVideoPlayer({
  src = DEMO_VIDEO,
  timestamps = DEFAULT_TIMESTAMPS,
  frames = [],
  autoPlay = true,
  muted = true,
  loop = true,
  className,
}: CustomVideoPlayerProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const videoRef = useRef<HTMLVideoElement>(null)
  const cursorRef = useRef<HTMLDivElement>(null)
  const markerRef = useRef<HTMLDivElement>(null)
  const [isPlaying, setIsPlaying] = useState(autoPlay)

  const handleTimeUpdate = useCallback(() => {
    const video = videoRef.current
    const marker = markerRef.current
    if (!(video && marker)) {
      return
    }
    const pct = (video.currentTime / video.duration) * 100
    marker.style.left = `calc(${pct}% - 1px)`
  }, [])

  const handleTimelineClick = useCallback(
    (e: React.MouseEvent<HTMLDivElement>) => {
      e.stopPropagation()
      const video = videoRef.current
      const marker = markerRef.current
      if (!(video && marker)) {
        return
      }
      const rect = e.currentTarget.getBoundingClientRect()
      const pct = (e.clientX - rect.left) / rect.width
      video.currentTime = pct * video.duration
      marker.style.left = `calc(${pct * 100}% - 1px)`
    },
    []
  )

  const handleOverlayClick = useCallback(() => {
    const video = videoRef.current
    if (!video) {
      return
    }
    if (isPlaying) {
      video.pause()
    } else {
      video.play()
    }
    setIsPlaying((prev) => !prev)
  }, [isPlaying])

  useEffect(() => {
    const prefersReduced = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches
    if (prefersReduced) {
      if (cursorRef.current) {
        cursorRef.current.style.display = "none"
      }
      return
    }

    const handleMouseMove = (e: MouseEvent) => {
      const cursor = cursorRef.current
      if (cursor) {
        cursor.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`
      }
    }
    document.addEventListener("mousemove", handleMouseMove)
    return () => document.removeEventListener("mousemove", handleMouseMove)
  }, [])

  return (
    <div className={`cvp-overlay ${className ?? ""}`.trim()} ref={containerRef}>
      <div className="cvp-video-container">
        <video
          ref={videoRef}
          autoPlay={autoPlay}
          muted={muted}
          loop={loop}
          playsInline
          onTimeUpdate={handleTimeUpdate}
        >
          <source src={src} type="video/mp4" />
        </video>
      </div>

      <div className="cvp-cursor" ref={cursorRef}>
        <p>{isPlaying ? "Pause" : "Play"}</p>
      </div>

      <div
        className="cvp-timeline"
        onClick={handleTimelineClick}
        onKeyDown={(e) => {
          if (e.key === "Enter") {
            handleOverlayClick()
          }
        }}
        aria-label="Video timeline"
        tabIndex={0}
        role="button"
      >
        <div className="cvp-marker" ref={markerRef} />
        <div className="cvp-timestamps">
          {timestamps.map((ts, i) => (
            <p key={i}>{ts.label}</p>
          ))}
        </div>
        {frames.length > 0 && (
          <div className="cvp-frames">
            {frames.map((frame, i) => (
              <div className="cvp-frame" key={i}>
                <img src={frame.image} alt="" />
              </div>
            ))}
          </div>
        )}
      </div>

      <button
        type="button"
        className="cvp-click-area"
        onClick={handleOverlayClick}
        aria-label={isPlaying ? "Pause video" : "Play video"}
      />
    </div>
  )
}

export default CustomVideoPlayer

.cvp-overlay {
  position: relative;
  width: 100%;
  height: 100%;
}

.cvp-video-container {
  position: fixed;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  min-width: 100%;
  min-height: 100%;
  overflow: hidden;
}

.cvp-video-container video {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cvp-timeline {
  position: absolute;
  bottom: 0;
  width: 100%;
  height: 160px;
  display: flex;
  flex-direction: column;
  padding: 1em;
  gap: 0.5em;
  cursor: pointer;
  z-index: 3;
}

.cvp-timestamps {
  position: relative;
  width: 100%;
  display: flex;
  justify-content: space-between;
}

.cvp-timestamps p {
  color: var(--cvp-fg, #fff);
  font-size: 13px;
  font-family: monospace;
}

.cvp-frames {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: space-between;
  gap: 1em;
  border-top: 1px dashed var(--cvp-fg, #fff);
  border-bottom: 1px dashed var(--cvp-fg, #fff);
  padding: 0.75em 0;
}

.cvp-frame {
  position: relative;
}

.cvp-frame::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.5);
  transition: 0.3s;
}

.cvp-frame:hover::after {
  background: rgba(0, 0, 0, 0);
}

.cvp-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.cvp-marker {
  position: absolute;
  bottom: 0.75em;
  left: 0;
  width: 2px;
  height: 150px;
  background: red;
  transition: left 0.5s linear;
  z-index: 2;
}

.cvp-marker::before {
  position: absolute;
  content: "";
  top: 0;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 10px;
  height: 10px;
  border-radius: 100%;
  background: red;
}

.cvp-cursor {
  position: absolute;
  top: 20px;
  left: 20px;
  text-transform: uppercase;
  transition: transform 1000ms cubic-bezier(0.075, 0.82, 0.165, 1);
  pointer-events: none;
  z-index: 4;
}

.cvp-cursor p {
  color: var(--cvp-fg, #fff);
  font-size: 13px;
  font-family: monospace;
}

.cvp-click-area {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: calc(100% - 160px);
  background: transparent;
  border: none;
  cursor: none;
  z-index: 2;
}

@media (max-width: 900px) {
  .cvp-timeline {
    height: 100px;
  }

  .cvp-timestamps p:nth-child(2),
  .cvp-timestamps p:nth-child(3),
  .cvp-timestamps p:nth-child(5),
  .cvp-timestamps p:nth-child(6),
  .cvp-timestamps p:nth-child(8),
  .cvp-timestamps p:nth-child(9),
  .cvp-timestamps p:nth-child(11),
  .cvp-timestamps p:nth-child(12) {
    display: none;
  }

  .cvp-frames {
    gap: 0.25em;
    border-bottom: none;
  }

  .cvp-marker {
    height: 100px;
  }

  .cvp-cursor {
    display: none;
  }

  .cvp-click-area {
    height: calc(100% - 100px);
    cursor: pointer;
  }
}
